1|// Pure music scheduler. The reader calls it with explicit nowSec values,
2|// so dwell, hysteresis, and hard cuts are testable without timers.
3|import { MUSIC_CONFIG, nextTrack, rankTracks, resolveConfig, scoreTrack } from "./music";
4|import type { MusicConfig, MusicManifest, SceneSignal } from "./music";
5|
6|export interface SchedulerState {
7|  currentId: string | null;
8|  currentStartedSec: number;
9|  activeSceneId: string | null;
10|  pendingSceneId: string | null;
11|  pendingSinceSec: number;
12|  overrideId: string | null;
13|  overrideSceneId: string | null;
14|}
15|
16|export interface ScheduleDecision {
17|  state: SchedulerState;
18|  switchToId: string | null;
19|  crossfadeSec: number;
20|  hardCut: boolean;
21|}
22|
23|export function initScheduler(): SchedulerState {
24|  return {
25|    currentId: null,
26|    currentStartedSec: 0,
27|    activeSceneId: null,
28|    pendingSceneId: null,
29|    pendingSinceSec: 0,
30|    overrideId: null,
31|    overrideSceneId: null,
32|  };
33|}
34|
35|function noChange(state: SchedulerState): ScheduleDecision {
36|  return { state, switchToId: null, crossfadeSec: 0, hardCut: false };
37|}
38|
39|function topRanked(
40|  signal: SceneSignal | null,
41|  manifest: MusicManifest,
42|  config: MusicConfig,
43|  excludeId?: string | null,
44|): { id: string; score: number } | null {
45|  if (signal === null) {
46|    const ids = [...manifest.tracks]
47|      .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
48|      .filter((t) => t.id !== excludeId);
49|    const first = ids[0];
50|    return first ? { id: first.id, score: 0 } : null;
51|  }
52|  const ranked = rankTracks(signal, manifest, config).filter((t) => t.id !== excludeId);
53|  const best = ranked[0];
54|  return best ? { id: best.id, score: scoreTrack(signal, best, config) } : null;
55|}
56|
57|// Pick the switch for a newly active scene: best score wins, but the
58|// current track holds unless the best beats it by switchMargin after
59|// minTrackSec, or by hardCutMargin at once (hard cut, short fade).
60|function evaluateSwitch(
61|  state: SchedulerState,
62|  signal: SceneSignal | null,
63|  manifest: MusicManifest,
64|  nowSec: number,
65|  config: MusicConfig,
66|): ScheduleDecision {
67|  if (signal === null) return noChange(state);
68|  const best = topRanked(signal, manifest, config);
69|  if (!best) return noChange(state);
70|  const current = manifest.tracks.find((t) => t.id === state.currentId) ?? null;
71|  if (!current || best.id === current.id) {
72|    if (!current) {
73|      return {
74|        state: { ...state, currentId: best.id, currentStartedSec: nowSec },
75|        switchToId: best.id,
76|        crossfadeSec: 0,
77|        hardCut: false,
78|      };
79|    }
80|    return noChange(state);
81|  }
82|  const gap = best.score - scoreTrack(signal, current, config);
83|  if (gap >= config.hardCutMargin) {
84|    return {
85|      state: { ...state, currentId: best.id, currentStartedSec: nowSec },
86|      switchToId: best.id,
87|      crossfadeSec: config.hardCutCrossfadeSec,
88|      hardCut: true,
89|    };
90|  }
91|  if (gap >= config.switchMargin && nowSec - state.currentStartedSec >= config.minTrackSec) {
92|    return {
93|      state: { ...state, currentId: best.id, currentStartedSec: nowSec },
94|      switchToId: best.id,
95|      crossfadeSec: config.crossfadeSec,
96|      hardCut: false,
97|    };
98|  }
99|  return noChange(state);
100|}
101|
102|function promote(
103|  state: SchedulerState,
104|  sceneId: string,
105|  signal: SceneSignal | null,
106|  manifest: MusicManifest,
107|  nowSec: number,
108|  config: MusicConfig,
109|): ScheduleDecision {
110|  const settled: SchedulerState = {
111|    ...state,
112|    activeSceneId: sceneId,
113|    pendingSceneId: null,
114|    pendingSinceSec: 0,
115|    overrideId: null,
116|    overrideSceneId: null,
117|  };
118|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config);
119|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
120|}
121|
122|// The reading position entered a scene. It becomes pending and the dwell
123|// clock restarts, so fast scrolling keeps only the newest scene. After
124|// the pending scene holds for dwellSec it becomes active. The first
125|// track ever plays at once, with no dwell.
126|export function observeScene(
127|  state: SchedulerState,
128|  sceneId: string,
129|  signal: SceneSignal | null,
130|  manifest: MusicManifest,
131|  nowSec: number,
132|  override?: Partial<MusicConfig>,
133|): ScheduleDecision {
134|  const config = resolveConfig(override ?? MUSIC_CONFIG);
135|  if (state.currentId === null) {
136|    return promote(state, sceneId, signal, manifest, nowSec, config);
137|  }
138|  if (sceneId === state.activeSceneId) {
139|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
140|  }
141|  if (sceneId !== state.pendingSceneId) {
142|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
143|  }
144|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
145|  return promote(state, sceneId, signal, manifest, nowSec, config);
146|}
147|
148|// Time passed: settle a pending scene whose dwell has expired, or
149|// re-check the active scene (a hold from minTrackSec may have expired).
150|// The reader passes the pending signal when one exists, else the active.
151|export function tickScheduler(
152|  state: SchedulerState,
153|  signal: SceneSignal | null,
154|  manifest: MusicManifest,
155|  nowSec: number,
156|  override?: Partial<MusicConfig>,
157|): ScheduleDecision {
158|  const config = resolveConfig(override ?? MUSIC_CONFIG);
159|  if (state.currentId === null) return noChange(state);
160|  if (state.pendingSceneId !== null) {
161|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
162|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config);
163|  }
164|  if (state.activeSceneId === null) return noChange(state);
165|  return evaluateSwitch(state, signal, manifest, nowSec, config);
166|}
167|
168|// Reader skip: the same-emotion Next rule, applied at once with the
169|// normal crossfade. The choice holds until the next scene change.
170|export function requestNext(
171|  state: SchedulerState,
172|  signal: SceneSignal | null,
173|  manifest: MusicManifest,
174|  nowSec: number,
175|  override?: Partial<MusicConfig>,
176|): ScheduleDecision {
177|  const config = resolveConfig(override ?? MUSIC_CONFIG);
178|  const next = nextTrack(signal, manifest, state.currentId, config);
179|  if (!next) return noChange(state);
180|  return {
181|    state: {
182|      ...state,
183|      currentId: next.id,
184|      currentStartedSec: nowSec,
185|      overrideId: next.id,
186|      overrideSceneId: state.activeSceneId,
187|    },
188|    switchToId: next.id,
189|    crossfadeSec: config.crossfadeSec,
190|    hardCut: false,
191|  };
192|}
193|
194|// A non-looping track ended: fade into the best remaining track,
195|// excluding the one that just ended.
196|export function noteTrackEnded(
197|  state: SchedulerState,
198|  signal: SceneSignal | null,
199|  manifest: MusicManifest,
200|  endedId: string,
201|  nowSec: number,
202|  override?: Partial<MusicConfig>,
203|): ScheduleDecision {
204|  const config = resolveConfig(override ?? MUSIC_CONFIG);
205|  const best = topRanked(signal, manifest, config, endedId);
206|  if (!best) return noChange(state);
207|  return {
208|    state: { ...state, currentId: best.id, currentStartedSec: nowSec },
209|    switchToId: best.id,
210|    crossfadeSec: config.crossfadeSec,
211|    hardCut: false,
212|  };
213|}
214|
215|export { MUSIC_CONFIG };

