1|// Track selection and manifest parsing. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|
6|// Hand label for the track: the single emotion it was made to carry.
7|export type TrackSource = "generated" | "jamendo" | "recording";
8|
9|export interface Track {
10|  id: string;
11|  src: string;
12|  title: string;
13|  emotion: EmotionId;
14|  vector: Vector8;
15|  intensity: number;
16|  tempo: number;
17|  durationSec: number;
18|  startSec: number;
19|  loop: boolean;
20|  source?: TrackSource;
21|  artist?: string;
22|  composer?: string;
23|  license?: string;
24|  attribution?: string;
25|  sourceUrl?: string;
26|}
27|
28|export interface MusicManifest {
29|  version: number;
30|  tracks: Track[];
31|}
32|
33|export interface SceneSignal {
34|  vector: Vector8;
35|  intensity: number;
36|  tempo: number;
37|}
38|
39|export type Similarity = (scene: SceneSignal, track: Track) => number;
40|
41|export interface MusicWeights {
42|  emotion: number;
43|  intensity: number;
44|  tempo: number;
45|}
46|
47|export interface MusicConfig {
48|  similarity: Similarity;
49|  weights: MusicWeights;
50|  switchMargin: number;
51|  dwellSec: number;
52|  minTrackSec: number;
53|  hardCutMargin: number;
54|  crossfadeSec: number;
55|  hardCutCrossfadeSec: number;
56|}
57|
58|// Renormalize the 8 entries to sum 1. Extra keys (such as a Jev
59|// "unknown" entry) are ignored. An all-zero vector stays all zero.
60|export function normalize8(vector: Record<string, number>): number[] {
61|  const values = EMOTIONS.map((id: EmotionId) => {
62|    const v = vector[id];
63|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
64|  });
65|  const sum = values.reduce((a, b) => a + b, 0);
66|  if (sum <= 0) return values.map(() => 0);
67|  return values.map((v) => v / sum);
68|}
69|
70|// Bhattacharyya affinity over the renormalized shapes, plus separate
71|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
72|export function bhattacharyyaSimilarity(scene: SceneSignal, track: Track): number {
73|  const s = normalize8(scene.vector);
74|  const t = normalize8(track.vector);
75|  let affinity = 0;
76|  for (let i = 0; i < s.length; i++) {
77|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
78|  }
79|  const weights = MUSIC_CONFIG.weights;
80|  return (
81|    weights.emotion * affinity +
82|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
83|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
84|  );
85|}
86|
87|// Cosine over buildFeatures output (vector plus weighted intensity and
88|// tempo). Kept as an alternative; it favors peaky scenes.
89|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
90|  const a = buildFeatures(scene);
91|  const b = buildFeatures(track);
92|  let dot = 0;
93|  let na = 0;
94|  let nb = 0;
95|  for (let i = 0; i < a.length; i++) {
96|    const x = a[i] ?? 0;
97|    const y = b[i] ?? 0;
98|    dot += x * y;
99|    na += x * x;
100|    nb += y * y;
101|  }
102|  if (na === 0 || nb === 0) return 0;
103|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
104|}
105|
106|export const MUSIC_CONFIG: MusicConfig = {
107|  similarity: bhattacharyyaSimilarity,
108|  weights: { emotion: 0.7, intensity: 0.15, tempo: 0.15 },
109|  switchMargin: 0.07,
110|  dwellSec: 20,
111|  minTrackSec: 45,
112|  hardCutMargin: 0.2,
113|  crossfadeSec: 3,
114|  hardCutCrossfadeSec: 1.5,
115|};
116|
117|export function resolveConfig(override?: Partial<MusicConfig>): MusicConfig {
118|  if (!override) return MUSIC_CONFIG;
119|  return {
120|    ...MUSIC_CONFIG,
121|    ...override,
122|    weights: override.weights ?? MUSIC_CONFIG.weights,
123|  };
124|}
125|
126|export function scoreTrack(
127|  scene: SceneSignal,
128|  track: Track,
129|  override?: Partial<MusicConfig>,
130|): number {
131|  return resolveConfig(override).similarity(scene, track);
132|}
133|
134|// Best score first. Ties go to the lower track id, so ranking is stable.
135|export function rankTracks(
136|  scene: SceneSignal,
137|  manifest: MusicManifest,
138|  override?: Partial<MusicConfig>,
139|): Track[] {
140|  const config = resolveConfig(override);
141|  return [...manifest.tracks].sort((a, b) => {
142|    const diff = config.similarity(scene, b) - config.similarity(scene, a);
143|    if (diff !== 0) return diff;
144|    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
145|  });
146|}
147|
148|// Dominant emotion of a scene: argmax of the renormalized vector, with
149|// ties broken by EMOTIONS order.
150|export function dominantEmotion(scene: SceneSignal): EmotionId {
151|  const norm = normalize8(scene.vector);
152|  let best: EmotionId = EMOTIONS[0] as EmotionId;
153|  let bestValue = -Infinity;
154|  EMOTIONS.forEach((id: EmotionId, i: number) => {
155|    const value = norm[i] ?? 0;
156|    if (value > bestValue) {
157|      bestValue = value;
158|      best = id;
159|    }
160|  });
161|  return best;
162|}
163|
164|// Reader skip rule: cycle tracks hand-labeled with the scene's dominant
165|// emotion, in score order, wrapping and skipping the current track. When
166|// the current track has another emotion, start at the top candidate. With
167|// no other same-emotion track, fall back to the best track overall that
168|// is not the current one. A null scene cycles all tracks in id order.
169|// One track or none gives null, and the UI disables the button then.
170|export function nextTrack(
171|  scene: SceneSignal | null,
172|  manifest: MusicManifest,
173|  currentTrackId: string | null,
174|  override?: Partial<MusicConfig>,
175|): Track | null {
176|  const tracks = manifest.tracks;
177|  if (tracks.length <= 1) return null;
178|  const config = resolveConfig(override);
179|  if (scene === null) {
180|    const ids = [...tracks].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
181|    const at = ids.findIndex((t) => t.id === currentTrackId);
182|    return ids[(at + 1) % ids.length] as Track;
183|  }
184|  const ranked = rankTracks(scene, manifest, config);
185|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
186|  const others = same.filter((t) => t.id !== currentTrackId);
187|  if (others.length > 0) {
188|    const at = same.findIndex((t) => t.id === currentTrackId);
189|    if (at >= 0) return same[(at + 1) % same.length] as Track;
190|    return same[0] as Track;
191|  }
192|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
193|}
194|
195|const SUPPORTED_VERSION = 2;
196|const SOURCES = ["generated", "jamendo", "recording"] as const;
197|
198|function isRecord(value: unknown): value is Record<string, unknown> {
199|  return typeof value === "object" && value !== null && !Array.isArray(value);
200|}
201|
202|function isOneOf<T extends string>(value: unknown, allowed: readonly T[]): value is T {
203|  return typeof value === "string" && allowed.some((entry) => entry === value);
204|}
205|
206|function isVector8(value: unknown): value is Vector8 {
207|  if (!isRecord(value)) return false;
208|  return EMOTIONS.every(
209|    (id: EmotionId) =>
210|      typeof value[id] === "number" &&
211|      Number.isFinite(value[id]) &&
212|      (value[id] as number) >= 0 &&
213|      (value[id] as number) <= 1,
214|  );
215|}
216|
217|function isUnit(value: unknown): value is number {
218|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1;
219|}
220|
221|function isSrc(value: unknown): value is string {
222|  return (
223|    typeof value === "string" && (value.startsWith("/music/") || value.startsWith("https://"))
224|  );
225|}
226|
227|function isNonEmptyString(value: unknown): value is string {
228|  return typeof value === "string" && value !== "";
229|}
230|
231|// Fail loudly on a bad drop-in manifest so broken files never play quiet.
232|export function parseManifest(json: unknown): MusicManifest {
233|  if (!isRecord(json)) throw new Error("manifest must be an object");
234|  if (json.version !== SUPPORTED_VERSION) {
235|    throw new Error(`unsupported manifest version: ${String(json.version)}`);
236|  }
237|  if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
238|  const tracks = json.tracks.map((entry, i) => {
239|    if (!isRecord(entry)) throw new Error(`track ${i} must be an object`);
240|    const { id, src, title, emotion, vector, intensity, tempo } = entry;
241|    const { durationSec, startSec, loop } = entry;
242|    const { source, artist, composer, license, attribution, sourceUrl } = entry;
243|    if (typeof id !== "string" || id === "") throw new Error(`track ${i} needs a string id`);
244|    if (!isSrc(src)) throw new Error(`track ${id} src must be a /music/ path or https URL`);
245|    if (typeof title !== "string" || title === "") throw new Error(`track ${id} needs a title`);
246|    if (!isOneOf(emotion, EMOTIONS)) {
247|      throw new Error(`track ${id} emotion must be one of the 8 emotion ids`);
248|    }
249|    if (!isVector8(vector)) throw new Error(`track ${id} vector must cover the 8 emotion ids`);
250|    if (!isUnit(intensity)) throw new Error(`track ${id} intensity must be 0..1`);
251|    if (!isUnit(tempo)) throw new Error(`track ${id} tempo must be 0..1`);
252|    if (typeof durationSec !== "number" || !Number.isFinite(durationSec) || durationSec <= 0) {
253|      throw new Error(`track ${id} durationSec must be a positive number`);
254|    }
255|    let start = 0;
256|    if (startSec !== undefined) {
257|      if (typeof startSec !== "number" || !Number.isFinite(startSec) || startSec < 0) {
258|        throw new Error(`track ${id} startSec must be >= 0`);
259|      }
260|      if (startSec >= durationSec) {
261|        throw new Error(`track ${id} startSec must be below durationSec`);
262|      }
263|      start = startSec;
264|    }
265|    let loops = true;
266|    if (loop !== undefined) {
267|      if (typeof loop !== "boolean") throw new Error(`track ${id} loop must be a boolean`);
268|      loops = loop;
269|    }
270|    let trackSource: TrackSource | undefined;
271|    if (source !== undefined) {
272|      if (!isOneOf(source, SOURCES)) {
273|        throw new Error(`track ${id} source must be generated, jamendo, or recording`);
274|      }
275|      trackSource = source;
276|    }
277|    const credit: { artist?: string; composer?: string; license?: string; attribution?: string } = {};
278|    const pairs = [
279|      ["artist", artist],
280|      ["composer", composer],
281|      ["license", license],
282|      ["attribution", attribution],
283|    ] as const;
284|    for (const [key, value] of pairs) {
285|      if (value === undefined) continue;
286|      if (!isNonEmptyString(value)) throw new Error(`track ${id} ${key} must be a non-empty string`);
287|      credit[key] = value;
288|    }
289|    if (sourceUrl !== undefined && (typeof sourceUrl !== "string" || !sourceUrl.startsWith("https://"))) {
290|      throw new Error(`track ${id} sourceUrl must be an https URL`);
291|    }
292|    return {
293|      id,
294|      src,
295|      title,
296|      emotion,
297|      vector,
298|      intensity,
299|      tempo,
300|      durationSec,
301|      startSec: start,
302|      loop: loops,
303|      ...credit,
304|      ...(trackSource === undefined ? {} : { source: trackSource }),
305|      ...(sourceUrl === undefined ? {} : { sourceUrl }),
306|    };
307|  });
308|  return { version: SUPPORTED_VERSION, tracks };
