57|    },
58|    [applyDecision],
59|  );
60|
61|  useEffect(() => {
62|    let cancelled = false;
63|    fetch("/music/manifest.json")
64|      .then((res) => {
65|        if (!res.ok) throw new Error(`manifest ${res.status}`);
66|        return res.json();
67|      })
68|      .then((json: unknown) => {
69|        if (cancelled) return;
70|        setManifest(parseManifest(json));
71|      })
72|      .catch(() => {
73|        if (!cancelled) setMusicFailed(true);
74|      });
75|    return () => {
76|      cancelled = true;
77|    };
78|  }, []);
